func:
// IEC104 commands already have the full structure from Story 2.1:
// {device_id, zone_id, action, value, unit, source, timestamp, event_id}
// Just pass through with source validation
// Story 2.4: preserve event_id for audit correlation

const cmd = msg.payload;

if (typeof cmd !== 'object' || cmd === null) {
    msg.command = { device_id: 'unknown', zone_id: 'unknown', action: 'unknown' };
    node.error('[modbus-writeback] ValidationError: IEC104 command payload is not an object', msg);
    return null;
}

msg.command = {
    device_id: cmd.device_id || '',
    zone_id: cmd.zone_id || '',
    action: cmd.action || '',
    value: cmd.value,
    unit: cmd.unit || '',
    source: cmd.source || 'iec104',
    timestamp: cmd.timestamp || Date.now(),
    event_id: cmd.event_id || ''
};

return msg;

// Cloud/direct commands arrive on topic: nexus/{zone_id}/{device_id}/command
// Extract zone_id and device_id from topic — topic is authoritative (security)

const parts = msg.topic.split('/');

if (parts.length !== 4 || parts[0] !== 'nexus' || parts[3] !== 'command') {
    msg.command = { device_id: 'unknown', zone_id: 'unknown', action: 'unknown' };
    node.error('[modbus-writeback] ValidationError: invalid command topic format: ' + msg.topic, msg);
    return null;
}

const cmd = msg.payload;

if (typeof cmd !== 'object' || cmd === null) {
    msg.command = { device_id: parts[2], zone_id: parts[1], action: 'unknown' };
    node.error('[modbus-writeback] ValidationError: command payload is not an object', msg);
    return null;
}

// Topic-derived device_id and zone_id are authoritative — payload cannot override
msg.command = {
    device_id: parts[2],
    zone_id: parts[1],
    action: cmd.action || '',
    value: cmd.value,
    unit: cmd.unit || '',
    source: 'cloud',
    timestamp: cmd.timestamp || Date.now()
};

return msg;

// Validate command fields, action, value range, and device existence
// Uses flow context for device registry and env vars for limits
// Story 2.4: include source and event_id in all error payloads for audit trail

const cmd = msg.command;

if (!cmd) {
    node.error('[modbus-writeback] ValidationError: no command object in message', msg);
    return [null, msg];
}

// Helper to build error payload with audit fields
function buildError(fields) {
    return Object.assign({
        source: cmd.source || '',
        event_id: cmd.event_id || '',
        retries_exhausted: false,
        timestamp: Date.now()
    }, fields);
}

// Required fields
if (!cmd.device_id) {
    msg.payload = buildError({
        device_id: cmd.device_id || 'unknown',
        zone_id: cmd.zone_id || 'unknown',
        action: cmd.action || 'unknown',
        value: cmd.value,
        error: "missing required field 'device_id'"
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: missing required field device_id');
    return [null, msg];
}

if (!cmd.action) {
    msg.payload = buildError({
        device_id: cmd.device_id,
        zone_id: cmd.zone_id || 'unknown',
        action: 'unknown',
        value: cmd.value,
        error: "missing required field 'action'"
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: missing required field action');
    return [null, msg];
}

if (cmd.value === undefined || cmd.value === null) {
    msg.payload = buildError({
        device_id: cmd.device_id,
        zone_id: cmd.zone_id || 'unknown',
        action: cmd.action,
        value: null,
        error: "missing required field 'value'"
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: missing required field value');
    return [null, msg];
}

// Validate action is supported
const supportedActions = ['set_export_limit_kw'];
if (!supportedActions.includes(cmd.action)) {
    msg.payload = buildError({
        device_id: cmd.device_id,
        zone_id: cmd.zone_id || 'unknown',
        action: cmd.action,
        value: cmd.value,
        error: "unsupported action '" + cmd.action + "'. Supported: " + supportedActions.join(', ')
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: unsupported action ' + cmd.action);
    return [null, msg];
}

// Validate value is numeric
const numValue = parseFloat(cmd.value);
if (isNaN(numValue) || !isFinite(numValue)) {
    msg.payload = buildError({
        device_id: cmd.device_id,
        zone_id: cmd.zone_id || 'unknown',
        action: cmd.action,
        value: cmd.value,
        error: "value is not a valid number: '" + cmd.value + "'"
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: non-numeric value ' + cmd.value);
    return [null, msg];
}

// Validate value range
const minLimit = parseFloat(env.get('MODBUS_EXPORT_LIMIT_MIN')) || 0;
const maxLimit = parseFloat(env.get('MODBUS_EXPORT_LIMIT_MAX')) || 100;

if (numValue < minLimit || numValue > maxLimit) {
    msg.payload = buildError({
        device_id: cmd.device_id,
        zone_id: cmd.zone_id || 'unknown',
        action: cmd.action,
        value: numValue,
        error: "value " + numValue + " out of safe range [" + minLimit + ", " + maxLimit + "]"
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: value ' + numValue + ' out of range [' + minLimit + ', ' + maxLimit + ']');
    return [null, msg];
}

// Validate device exists in registry
const deviceRegistry = flow.get('deviceRegistry') || {};
const device = deviceRegistry[cmd.device_id];

if (!device) {
    msg.payload = buildError({
        device_id: cmd.device_id,
        zone_id: cmd.zone_id || 'unknown',
        action: cmd.action,
        value: numValue,
        error: "device '" + cmd.device_id + "' not found in registry"
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: unknown device ' + cmd.device_id);
    return [null, msg];
}

// Resolve action to register
const actionMap = flow.get('actionMap') || {};
const registerInfo = actionMap[cmd.action];

if (!registerInfo) {
    msg.payload = buildError({
        device_id: cmd.device_id,
        zone_id: cmd.zone_id || 'unknown',
        action: cmd.action,
        value: numValue,
        error: "no register mapping for action '" + cmd.action + "'"
    });
    msg.topic = 'nexus/internal/writeback-errors';
    node.warn('[modbus-writeback] ValidationError: no register mapping for ' + cmd.action);
    return [null, msg];
}

// Scale value for register write
const scaleFactor = registerInfo.scale_factor || 1;
const registerValue = Math.round(numValue / scaleFactor);

// Build validated command with Modbus addressing
msg.command = cmd;
msg.command.value = numValue;
msg.modbusDevice = device;
msg.modbusRegister = registerInfo;
msg.registerValue = registerValue;
msg.originalValue = numValue;
msg.retryCount = msg.retryCount || 0;

// Set Modbus write parameters
msg.payload = {
    value: registerValue,
    fc: 6,
    unitid: device.unit_id,
    address: registerInfo.register_address,
    quantity: 1
};

return [msg, null];

// Initialize device registry and action-to-register mapping in flow context.
// In production, this would be loaded from a config file or ThingsBoard attributes.
// For now, uses sensible defaults for a single inverter setup.

// Device registry: device_id -> Modbus connection details
const deviceRegistry = {
    "inverter-01": {
        modbus_host: env.get('MODBUS_HOST') || '127.0.0.1',
        modbus_port: parseInt(env.get('MODBUS_PORT')) || 502,
        unit_id: parseInt(env.get('MODBUS_RTU_UNIT_ID')) || 1,
        protocol: 'tcp'
    }
};

// Action-to-register mapping: action -> Modbus register details
// register_address: Modbus register to write
// data_type: HoldingRegister
// scale_factor: value_in_kw * (1/scale_factor) = register_value
//   e.g., 50.0 kW / 0.1 = 500 (register stores 1 decimal place)
const actionMap = {
    "set_export_limit_kw": {
        register_address: 100,
        register_type: "HoldingRegister",
        data_type: "INT16",
        scale_factor: 0.1,
        telemetry_key: "export_limit_kw"
    }
};

flow.set('deviceRegistry', deviceRegistry);
flow.set('actionMap', actionMap);

node.log('[modbus-writeback] Device registry initialized: ' + Object.keys(deviceRegistry).length + ' devices, ' + Object.keys(actionMap).length + ' actions');

return null;

// Prepare msg for node-red-contrib-modbus write node
// The modbus-write node expects:
// msg.payload.value (or msg.payload as array for FC16)
// msg.payload.unitid, msg.payload.fc, msg.payload.address, msg.payload.quantity
//
// Since we set keepMsgProperties=true, our command context persists.

const device = msg.modbusDevice;
const register = msg.modbusRegister;
const registerValue = msg.registerValue;

// For FC6 (Write Single Register), payload is the value
msg.payload = {
    value: registerValue,
    fc: 6,
    unitid: device.unit_id,
    address: register.register_address,
    quantity: 1
};

return msg;

// After modbus-write, msg.payload is the write response.
// Re-set msg.payload with read parameters so modbus-read knows
// which register to read back for verification.

const device = msg.modbusDevice;
const register = msg.modbusRegister;

msg.payload = {
    fc: 3,
    unitid: device.unit_id,
    address: register.register_address,
    quantity: 1
};

return msg;

// Compare written value with read-back value
// msg.payload = array of register values from modbus-read
// msg.registerValue = value that was written
// msg.originalValue = original command value in kW
// msg.modbusRegister.scale_factor = conversion factor

const readValues = msg.payload;
const writtenValue = msg.registerValue;
const tolerance = 1; // 1 register unit tolerance for rounding

if (!Array.isArray(readValues) || readValues.length === 0) {
    // Read-back failed — treat as write failure
    msg.verifyError = 'read-back returned empty or invalid data';
    return [null, msg];
}

const readValue = readValues[0];
const diff = Math.abs(readValue - writtenValue);

if (diff > tolerance) {
    // Mismatch — treat as write failure
    msg.verifyError = 'read-back mismatch — wrote ' + writtenValue + ', read ' + readValue;
    return [null, msg];
}

// Verification passed
return [msg, null];

// Handle write/verify failures with retry logic
// Max 1 retry (retryCount starts at 0)

const maxRetries = 1;
const retryCount = msg.retryCount || 0;
const cmd = msg.command || {};
const errorReason = msg.verifyError || (msg.error ? msg.error.message : 'Modbus write failed');

if (retryCount < maxRetries) {
    // Retry: increment count and re-route to write
    msg.retryCount = retryCount + 1;
    node.warn('[modbus-writeback] RetryAttempt: ' + errorReason + ' — retry ' + msg.retryCount + '/' + maxRetries + ' for device ' + cmd.device_id);
    return [msg, null];
}

// Retries exhausted: publish error (includes event_id for Story 2.4 audit trail)
msg.payload = {
    device_id: cmd.device_id || 'unknown',
    zone_id: cmd.zone_id || 'unknown',
    action: cmd.action || 'unknown',
    value: msg.originalValue,
    error: errorReason,
    retries_exhausted: true,
    timestamp: Date.now(),
    source: cmd.source || '',
    event_id: cmd.event_id || ''
};
msg.topic = 'nexus/internal/writeback-errors';

node.warn('[modbus-writeback] ModbusError: ' + errorReason + ' — retries exhausted for device ' + cmd.device_id);

return [null, msg];

// Build confirmation message and telemetry update
// Output 1: writeback-status confirmation
// Output 2: telemetry update
// Story 2.4: include event_id for audit correlation

const cmd = msg.command || {};
const register = msg.modbusRegister || {};
const now = Date.now();

// Confirmation message (includes event_id for Story 2.4 audit trail)
const confirmation = {
    device_id: cmd.device_id,
    zone_id: cmd.zone_id,
    action: cmd.action,
    value: msg.originalValue,
    register_address: register.register_address,
    status: 'confirmed',
    source: cmd.source,
    timestamp: now,
    event_id: cmd.event_id || ''
};

// Telemetry update — use command timestamp for ThingsBoard ordering accuracy
const telemetryKey = register.telemetry_key || 'export_limit_kw';
const telemetry = {
    ts: cmd.timestamp || now,
    values: {}
};
telemetry.values[telemetryKey] = msg.originalValue;

const msg1 = {
    payload: confirmation,
    topic: 'nexus/internal/writeback-status'
};

const msg2 = {
    payload: telemetry,
    topic: 'nexus/' + cmd.zone_id + '/' + cmd.device_id + '/telemetry'
};

node.log('[modbus-writeback] WriteConfirmed: ' + cmd.action + '=' + msg.originalValue + ' for device ' + cmd.device_id);

return [msg1, msg2];

// Format caught errors for logging and publishing
// Story 2.4: include source and event_id for audit trail
const errorSource = msg.error ? msg.error.source : {};
const errorMsg = msg.error ? msg.error.message : 'Unknown error';
const nodeName = errorSource.name || errorSource.id || 'unknown';
const cmd = msg.command || {};

node.warn('[modbus-writeback] ' + nodeName + ': ' + errorMsg);

msg.payload = {
    device_id: cmd.device_id || 'unknown',
    zone_id: cmd.zone_id || 'unknown',
    action: cmd.action || 'unknown',
    value: msg.originalValue || null,
    error: '[modbus-writeback] ' + nodeName + ': ' + errorMsg,
    retries_exhausted: false,
    timestamp: Date.now(),
    source: cmd.source || '',
    event_id: cmd.event_id || ''
};
msg.topic = 'nexus/internal/writeback-errors';

return msg;
